contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address caller, bool status) public {
        require(logger != address(0));
        require(caller != address(0));

        c.setApprovedLogger(logger, status);

        bool loggerBefore = c.approvedLoggers(logger);

        bool revertCreated;
        bool createdResult;
        try c.logCreated(caller) returns (bool success) {
            createdResult = success;
            revertCreated = false;
        } catch {
            createdResult = true;
            revertCreated = true;
        }

        bool revertRedemption;
        bool redemptionResult;
        try c.logRedemptionRequested(caller, bytes32(0), 0, bytes(""), 0, bytes("")) returns (bool success) {
            redemptionResult = success;
            revertRedemption = false;
        } catch {
            redemptionResult = true;
            revertRedemption = true;
        }

        bool loggerAfter = c.approvedLoggers(logger);

        bool anyRejected = (!loggerBefore && !createdResult) || (!loggerBefore && !redemptionResult);
        bool allAccepted = loggerBefore && createdResult && redemptionResult;
        bool loggerStable = loggerBefore == loggerAfter;

        assert(loggerStable && (anyRejected || allAccepted));
    }

    receive() external payable {}
}

