contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0));

        // Ensure the test contract is an approved logger so the positive case is exercised.
        c.setApprovedLogger(address(this), true);
        bool approvedBefore = c.approvedToLog(address(this));

        bool createdReturned;
        bool createdReverted;
        try c.logCreated(caller) returns (bool success) {
            createdReturned = success;
            createdReverted = false;
        } catch {
            createdReverted = true;
        }

        bool redemptionReturned;
        bool redemptionReverted;
        try c.logRedemptionRequested(caller, bytes32(0), 0, bytes(""), 0, bytes("")) returns (bool success) {
            redemptionReturned = success;
            redemptionReverted = false;
        } catch {
            redemptionReverted = true;
        }

        // Deactivate approval and call a log function again to cover the false path.
        c.setApprovedLogger(address(this), false);
        bool approvedAfter = c.approvedToLog(address(this));

        bool unapprovedReturned;
        bool unapprovedReverted;
        try c.logFunded() returns (bool success) {
            unapprovedReturned = success;
            unapprovedReverted = false;
        } catch {
            unapprovedReverted = true;
        }

        bool unapprovedAfter = c.approvedToLog(address(this));

        assert(
            approvedBefore == true &&
            !createdReverted && createdReturned == true &&
            !redemptionReverted && redemptionReturned == true &&
            approvedAfter == false &&
            !unapprovedReverted && unapprovedReturned == false &&
            unapprovedAfter == false
        );
    }

    receive() external payable {}
}

