contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, bool approve, uint256 choice, address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint, bytes32 _r, bytes32 _s, bytes32 _txid, bool _wasFraud) public {
        c.setApprovedLogger(logger, approve);

        if (approve) {
            require(c.approvedToLog(logger), "approved logger should be set");
        } else {
            require(!c.approvedToLog(logger), "logger should not be approved");
        }

        bool ok1;
        bool ok2;
        bool ok3;
        bool ok4;
        bool ok5;
        bool ok6;
        bool ok7;
        bool ok8;
        bool ok9;
        bool ok10;
        bool ok11;
        bool ok12;

        if (choice == 0) {
            ok1 = c.logCreated(_requester);
            assert(ok1 == approve && ok1 == c.approvedToLog(address(this)));
        } else if (choice == 1) {
            ok2 = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
            assert(ok2 == approve && ok2 == c.approvedToLog(address(this)));
        } else if (choice == 2) {
            ok3 = c.logGotRedemptionSignature(_digest, _r, _s);
            assert(ok3 == approve && ok3 == c.approvedToLog(address(this)));
        } else if (choice == 3) {
            ok4 = c.logRegisteredPubkey(_r, _s);
            assert(ok4 == approve && ok4 == c.approvedToLog(address(this)));
        } else if (choice == 4) {
            ok5 = c.logSetupFailed();
            assert(ok5 == approve && ok5 == c.approvedToLog(address(this)));
        } else if (choice == 5) {
            ok6 = c.logFraudDuringSetup();
            assert(ok6 == approve && ok6 == c.approvedToLog(address(this)));
        } else if (choice == 6) {
            ok7 = c.logFunded();
            assert(ok7 == approve && ok7 == c.approvedToLog(address(this)));
        } else if (choice == 7) {
            ok8 = c.logCourtesyCalled();
            assert(ok8 == approve && ok8 == c.approvedToLog(address(this)));
        } else if (choice == 8) {
            ok9 = c.logStartedLiquidation(_wasFraud);
            assert(ok9 == approve && ok9 == c.approvedToLog(address(this)));
        } else if (choice == 9) {
            ok10 = c.logRedeemed(_txid);
            assert(ok10 == approve && ok10 == c.approvedToLog(address(this)));
        } else if (choice == 10) {
            ok11 = c.logLiquidated();
            assert(ok11 == approve && ok11 == c.approvedToLog(address(this)));
        } else {
            ok12 = c.logExitedCourtesyCall();
            assert(ok12 == approve && ok12 == c.approvedToLog(address(this)));
        }
    }

    receive() external payable {}
}

