contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address logger, bool status, address keepAddress, address other) public payable {
        // setup: set approval for `logger`
        c.setApprovedLogger(logger, status);

        // read approval state via public getter
        bool approved = c.approvedToLog(logger);

        // make the deciding call from this test contract (msg.sender)
        bool returned = c.logCreated(keepAddress);

        // general rule: logCreated's return value equals the caller's approval status
        assert(returned == approved);

        // also ensure approval status is unaffected by the log call
        assert(c.approvedToLog(logger) == approved);

        // and that approval for a distinct address remains false
        assert(!c.approvedToLog(other));
    }

    receive() external payable {}
}

